import type { Book, BookStatus } from '../../types';

export const STATUS_LABELS: Record<BookStatus, string> = {
  reading: 'Reading',
  'to-read': 'To Read',
  read: 'Read',
  dnf: 'Did Not Finish',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: BookStatus): string {
  const map: Record<BookStatus, string> = {
    reading: 'status-reading',
    'to-read': 'status-to-read',
    read: 'status-read',
    dnf: 'status-dnf',
  };
  return map[status];
}

interface StatusListProps {
  items: Book[] | null;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item status-list-item--skeleton">
            <span className="status-list-skeleton-title" />
            <span className="status-list-skeleton-author" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped = (Object.keys(STATUS_LABELS) as BookStatus[]).reduce<
    Record<BookStatus, Book[]>
  >(
    (acc, status) => {
      acc[status] = items.filter((item) => item.status === status);
      return acc;
    },
    { reading: [], 'to-read': [], read: [], dnf: [] },
  );

  return (
    <div className="status-list">
      {(Object.entries(STATUS_LABELS) as [BookStatus, string][]).map(([status, label]) => {
        const group = grouped[status];
        if (group.length === 0) {
          return null;
        }
        return (
          <section key={status} className={`status-group ${statusColor(status)}`}>
            <h2 className="status-group-heading">{label}</h2>
            <ul className="status-group-list">
              {group.map((book) => (
                <li key={book.id} className="status-list-item">
                  <span className="status-list-item-title">{book.title}</span>
                  <span className="status-list-item-author">{book.author}</span>
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

