import { useState } from 'react';

const CHIP_LABELS = ['All', 'Active', 'Archived', 'Starred'] as const;
type ChipLabel = (typeof CHIP_LABELS)[number];

const chipFilterStyles = `
@layer components {
  --shelf-chip-filter-gap: var(--shelf-space-2);
  --shelf-chip-filter-padding-x: var(--shelf-space-3);
  --shelf-chip-filter-padding-y: var(--shelf-space-1);
  --shelf-chip-filter-radius: var(--shelf-radius-full);
  --shelf-chip-filter-font-size: var(--shelf-font-size-sm);
  --shelf-chip-filter-font-weight: var(--shelf-font-weight-medium);
  --shelf-chip-filter-border-width: var(--shelf-borderWidth-thin);

  .chip-filter {
    display: flex;
    gap: var(--shelf-chip-filter-gap);
  }

  .chip-filter-button {
    padding: var(--shelf-chip-filter-padding-y) var(--shelf-chip-filter-padding-x);
    border-radius: var(--shelf-chip-filter-radius);
    border: var(--shelf-chip-filter-border-width) solid var(--shelf-color-border);
    background-color: var(--shelf-color-surface);
    color: var(--shelf-color-text);
    font-size: var(--shelf-chip-filter-font-size);
    font-weight: var(--shelf-chip-filter-font-weight);
    line-height: var(--shelf-line-height-base);
    cursor: pointer;
  }

  .chip-filter-button[aria-pressed="true"] {
    background-color: var(--shelf-color-gray-700);
    color: var(--shelf-color-white);
    border-color: var(--shelf-color-gray-700);
  }
}
`;

interface ChipFilterProps {
  onFilterChange?: (filter: ChipLabel) => void;
}

export function ChipFilter({ onFilterChange }: ChipFilterProps): JSX.Element {
  const [active, setActive] = useState<ChipLabel>('All');

  function handleClick(label: ChipLabel): void {
    setActive(label);
    onFilterChange?.(label);
  }

  return (
    <>
      <style>{chipFilterStyles}</style>
      <div className="chip-filter" role="group" aria-label="Filter books">
        {CHIP_LABELS.map((label) => (
          <button
            key={label}
            className="chip-filter-button"
            aria-pressed={active === label}
            onClick={() => handleClick(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}

