interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  // Math.ceil avoids under-charging: always round up to the next cent
  const display = (cents: number): string =>
    (Math.ceil(cents) / 100).toFixed(2);

  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      {hasDiscount && (
        <s className="price-display-original">${display(originalPrice!)}</s>
      )}
      <span className="price-display-current">${display(price)}</span>
    </span>
  );
}

