  return (
    <table className="data-table" role="table">
      <thead>
        <tr>
          {columns.map((col) => (
            <th key={col} scope="col" className="data-table-th">
              {col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: SKELETON_COUNT }, (_, i) => (
              <tr key={i}>
                {columns.map((col) => (
                  <td key={col} className="data-table-td">
                    <span className="data-table-skeleton-cell" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row) => (
              <tr key={row.id}>
                {row.cells.map((cell, i) => (
                  // eslint-disable-next-line react/no-array-index-key
                  <td key={i} className="data-table-td">
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}

