import './ChipBar.css';
import type { BookStatus } from '../../types';

interface ChipBarProps {
  statuses: BookStatus[];
  selected: Set<BookStatus>;
  onSelectionChange: (next: Set<BookStatus>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: BookStatus): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="group" aria-label="Filter by status">
      {statuses.map((status) => (
        <button
          key={status}
          className="chip-bar-button"
          aria-pressed={selected.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

